function resolvePromptContent(content, params) {
  const activeFileHint = params.activeFile ? ` (active file: ${params.activeFile})` : "";
  return content.replace(/\{\{userInput\}\}/g, params.userInput ?? "").replace(/\{\{activeFile\}\}/g, params.activeFile ?? "").replace(/\{activeFile\}/g, params.activeFile ?? "").replace(/\$\{userInput\}/g, params.userInput ?? "").replace(/\$\{activeFileHint\}/g, activeFileHint).trim();
}

