var import_obsidian7 = require("obsidian");
async function testModelConnection(model) {
  try {
    const lp = modelToLLMProvider({ ...model, maxTokens: 16 });
    const handler = buildApiHandler(lp);
    const abort = new AbortController();
    const timeoutMs = model.provider === "ollama" ? 3e4 : 8e3;
    const timer = setTimeout(() => abort.abort(), timeoutMs);
    try {
      const stream = handler.createMessage(
        "You are a test.",
        [{ role: "user", content: "Hi" }],
        [],
        abort.signal
      );
      for await (const chunk of stream) {
        if (chunk.type === "text" || chunk.type === "usage") break;
      }
      return { ok: true, message: "Connection successful \u2713" };
    } finally {
      clearTimeout(timer);
    }
  } catch (err) {
    const isOllama = model.provider === "ollama";
    const errObj = err;
    const msg = errObj?.message ?? "";
    const s = errObj?.status;
    const isNetworkError = !s && (msg.includes("Failed to fetch") || msg.includes("NetworkError") || msg.includes("ECONNREFUSED") || msg.includes("ERR_CONNECTION_REFUSED"));
    if (errObj?.name === "AbortError") {
      return {
        ok: false,
        message: isOllama ? "Connection timed out (30 s)" : "Connection timed out (8 s)",
        detail: isOllama ? "Ollama did not respond in time. Two possible causes:\n\n1. Ollama is not running \u2192 start it: ollama serve\n2. The model is large and still loading into memory \u2192 wait a moment and try again." : "The server did not respond in time. Check your Base URL."
      };
    }
    if (isNetworkError) {
      return {
        ok: false,
        message: "Cannot connect to server",
        detail: isOllama ? "Ollama is not reachable at the Base URL. Make sure Ollama is running \u2014 it should start automatically after installation. You can also start it manually: ollama serve" : "Check that the Base URL is correct and the server is running."
      };
    }
    if (s === 401) {
      return {
        ok: false,
        message: "Invalid API key (401)",
        detail: model.provider === "anthropic" ? "The key should start with sk-ant-... Get it from console.anthropic.com \u2192 API Keys." : model.provider === "openai" ? "The key should start with sk-... Get it from platform.openai.com \u2192 API Keys." : "Check that you copied the full API key from your provider dashboard."
      };
    }
    if (s === 404) {
      if (isOllama) {
        return {
          ok: false,
          message: `Model "${model.name}" not found in Ollama`,
          detail: `The model name must match exactly what Ollama has installed.

1. Open a Terminal and run: ollama list
2. Copy the exact name shown (e.g. llama3.2:latest)
3. Paste it into the Model ID field above.

If the model is not installed yet: ollama pull ${model.name}`
        };
      }
      return {
        ok: false,
        message: "Model not found (404)",
        detail: "The Model ID does not exist for this provider. Check the exact model name in your provider's documentation."
      };
    }
    if (s === 429) {
      return { ok: false, message: "Rate limit reached (429)", detail: "You've sent too many requests. Wait a moment and try again." };
    }
    if (s === 403) {
      return { ok: false, message: "Access denied (403)", detail: "Your API key may not have permission to use this model, or billing is required." };
    }
    return { ok: false, message: "Connection failed", detail: msg || "Unknown error" };
  }
}
