// src/ui/settings/ContentEditorModal.ts
var import_obsidian20 = require("obsidian");
init_i18n();
var ContentEditorModal = class extends import_obsidian20.Modal {
  initialContent;
  onSave;
  modalTitle;
  constructor(app, title, initialContent, onSave) {
    super(app);
    this.modalTitle = title;
    this.initialContent = initialContent;
    this.onSave = onSave;
  }
  onOpen() {
    const { contentEl } = this;
    contentEl.addClass("content-editor-modal");
    contentEl.createEl("h3", { cls: "content-editor-title", text: this.modalTitle });
    const textarea = contentEl.createEl("textarea", { cls: "content-editor-textarea" });
    textarea.value = this.initialContent;
    textarea.setAttribute("rows", "20");
    textarea.setAttribute("spellcheck", "false");
    const btnRow = contentEl.createDiv({ cls: "content-editor-btn-row" });
    const saveBtn = btnRow.createEl("button", { text: t("modal.modelConfig.save"), cls: "mod-cta" });
    const cancelBtn = btnRow.createEl("button", { text: t("modal.modelConfig.cancel") });
    saveBtn.addEventListener("click", () => {
      this.onSave(textarea.value);
      this.close();
    });
    cancelBtn.addEventListener("click", () => this.close());
    setTimeout(() => {
      textarea.focus();
      textarea.setSelectionRange(textarea.value.length, textarea.value.length);
    }, 50);
  }
  onClose() {
    this.contentEl.empty();
  }
};

// src/core/context/RulesLoader.ts
var RulesLoader = class {
  fs;
  rulesDir;
  constructor(fs3) {
    this.fs = fs3;
    this.rulesDir = "rules";
  }
  /**
   * Ensure the rules directory exists (create if needed).
   */
  async initialize() {
    try {
      const exists = await this.fs.exists(this.rulesDir);
      if (!exists) {
        await this.fs.mkdir(this.rulesDir);
      }
    } catch {
    }
  }
  /**
   * Discover all rule files in the rules directory.
   * Returns paths relative to the FileAdapter root (e.g. "rules/my-rule.md").
   */
  async discoverRules() {
    try {
      const exists = await this.fs.exists(this.rulesDir);
      if (!exists) return [];
      const listed = await this.fs.list(this.rulesDir);
      return listed.files.filter((f) => f.endsWith(".md") || f.endsWith(".txt")).sort();
    } catch {
      return [];
    }
  }
  /**
   * Load all enabled rule files into a combined string.
   * A rule is enabled if `toggles[path]` is not explicitly `false`.
   * (New rules default to enabled.)
   */
  async loadEnabledRules(toggles) {
    const paths = await this.discoverRules();
    const parts = [];
    for (const rPath of paths) {
      if (toggles[rPath] === false) continue;
      try {
        const content = await this.fs.read(rPath);
        if (content.trim()) {
          const limited = content.length > 5e4 ? content.slice(0, 5e4) : content;
          parts.push(limited.trim());
        }
      } catch {
      }
    }
    return parts.join("\n\n");
  }
  /**
   * Create a new rule file. Returns the path of the created file.
   */
  async createRule(name, content) {
    await this.initialize();
    const safeName = name.replace(/[^a-zA-Z0-9\-_ ]/g, "").trim() || "rule";
    const rPath = `${this.rulesDir}/${safeName}.md`;
    await this.fs.write(rPath, content);
    return rPath;
  }
  /**
   * Delete a rule file.
   */
  async deleteRule(rPath) {
    await this.fs.remove(rPath);
  }
  /**
   * Read a rule file's content (for UI editing).
   */
  async readFile(rPath) {
    return this.fs.read(rPath);
  }
  /**
   * Write a rule file's content (for UI editing).
   */
  async writeFile(rPath, content) {
    await this.fs.write(rPath, content);
  }
  /**
   * Extract the display name from a rule path (filename without extension).
   */
  static displayName(rPath) {
    const parts = rPath.split("/");
    const filename = parts[parts.length - 1] ?? rPath;
    return filename.replace(/\.(md|txt)$/, "");
  }
};

// src/ui/settings/RulesTab.ts
init_i18n();
var RulesTab = class {
  constructor(plugin, app, rerender) {
    this.plugin = plugin;
    this.app = app;
    this.rerender = rerender;
  }
  build(containerEl) {
    containerEl.createEl("h3", { text: t("settings.rules.heading") });
    containerEl.createEl("p", {
      cls: "agent-settings-desc",
      text: t("settings.rules.desc")
    });
    const rulesLoader = this.plugin.rulesLoader;
    const createRow = containerEl.createDiv({ cls: "agent-rules-create-row" });
    const nameInput = createRow.createEl("input", {
      type: "text",
      placeholder: t("settings.rules.placeholder"),
      cls: "agent-rules-name-input"
    });
    const createBtn = createRow.createEl("button", { text: t("settings.rules.create"), cls: "mod-cta" });
    const importBtn = createRow.createEl("button", { text: t("settings.rules.import"), cls: "agent-rules-import-btn" });
    importBtn.addEventListener("click", () => {
      const fileInput = document.createElement("input");
      fileInput.type = "file";
      fileInput.accept = ".md,.txt";
      fileInput.addEventListener("change", async () => {
        const file = fileInput.files?.[0];
        if (!file || !rulesLoader) return;
        const content = await file.text();
        const nameWithoutExt = file.name.replace(/\.[^.]+$/, "");
        try {
          await rulesLoader.createRule(nameWithoutExt, content);
          await refreshList();
        } catch {
          new import_obsidian21.Notice(t("settings.rules.importFailed"));
        }
      });
      fileInput.click();
    });
    const listEl = containerEl.createDiv({ cls: "agent-rules-list" });
    const refreshList = async () => {
      listEl.empty();
      if (!rulesLoader) {
        listEl.createEl("p", { cls: "agent-empty-state", text: t("settings.rules.loaderNotAvailable") });
        return;
      }
      const paths = await rulesLoader.discoverRules();
      if (paths.length === 0) {
        listEl.createEl("p", { cls: "agent-empty-state", text: t("settings.rules.empty") });
        return;
      }
      for (const rPath of paths) {
        const row = listEl.createDiv({ cls: "agent-rules-row" });
        const label = row.createSpan({ cls: "agent-rules-label" });
        label.createSpan({ text: RulesLoader.displayName(rPath) });
        const actions = row.createDiv({ cls: "agent-rules-actions" });
        const editBtn = actions.createEl("button", { cls: "agent-rules-edit-btn" });
        (0, import_obsidian21.setIcon)(editBtn, "pencil");
        editBtn.setAttribute("aria-label", t("settings.rules.edit"));
        editBtn.addEventListener("click", async () => {
          const content = await rulesLoader.readFile(rPath);
          new ContentEditorModal(this.app, t("settings.rules.editRule", { name: RulesLoader.displayName(rPath) }), content, async (newContent) => {
            await rulesLoader.writeFile(rPath, newContent);
          }).open();
        });
        const exportBtn = actions.createEl("button", { cls: "agent-rules-export-btn" });
        (0, import_obsidian21.setIcon)(exportBtn, "download");
        exportBtn.setAttribute("aria-label", t("settings.rules.export"));
        exportBtn.addEventListener("click", async () => {
          const content = await rulesLoader.readFile(rPath);
          const blob = new Blob([content], { type: "text/markdown" });
          const url2 = URL.createObjectURL(blob);
          const a = document.createElement("a");
          a.href = url2;
          a.download = `${RulesLoader.displayName(rPath)}.md`;
          a.click();
          URL.revokeObjectURL(url2);
        });
        const delBtn = actions.createEl("button", { cls: "agent-rules-delete-btn" });
        (0, import_obsidian21.setIcon)(delBtn, "trash-2");
        delBtn.setAttribute("aria-label", t("settings.rules.delete"));
        delBtn.addEventListener("click", async () => {
          await rulesLoader.deleteRule(rPath);
          this.plugin.settings.rulesToggles ??= {};
          delete this.plugin.settings.rulesToggles[rPath];
          await this.plugin.saveSettings();
          await refreshList();
        });
        this.plugin.settings.rulesToggles ??= {};
        const isActive = this.plugin.settings.rulesToggles[rPath] !== false;
        const toggleEl = row.createDiv({
          cls: `checkbox-container agent-rules-toggle${isActive ? " is-enabled" : ""}`
        });
        toggleEl.addEventListener("click", async () => {
          this.plugin.settings.rulesToggles ??= {};
          const current2 = this.plugin.settings.rulesToggles[rPath] !== false;
          this.plugin.settings.rulesToggles[rPath] = !current2;
          await this.plugin.saveSettings();
          toggleEl.toggleClass("is-enabled", !current2);
        });
      }
    };
    createBtn.addEventListener("click", async () => {
      const name = nameInput.value.trim();
      if (!name || !rulesLoader) return;
      const template = `# ${name}

`;
      const rPath = await rulesLoader.createRule(name, template);
      nameInput.value = "";
      await refreshList();
      new ContentEditorModal(this.app, t("settings.rules.editRule", { name }), template, async (content) => {
        await rulesLoader.writeFile(rPath, content);
      }).open();
    });
    refreshList();
  }
};

