// src/core/tools/agent/EnablePluginTool.ts
var EnablePluginTool = class extends BaseTool {
  name = "enable_plugin";
  isWriteOperation = true;
  // Requires approval — changes plugin state
  constructor(plugin) {
    super(plugin);
  }
  getDefinition() {
    return {
      name: "enable_plugin",
      description: "Enable or disable an installed Obsidian community plugin. Use this when the user agrees to activate a disabled plugin that can help with their task. After enabling, wait briefly for commands to register, then use execute_command.",
      input_schema: {
        type: "object",
        properties: {
          plugin_id: {
            type: "string",
            description: 'The plugin ID to enable or disable (e.g., "dbfolder", "obsidian-kanban", "dataview").'
          },
          enable: {
            type: "boolean",
            description: "true to enable the plugin, false to disable it. Defaults to true."
          }
        },
        required: ["plugin_id"]
      }
    };
  }
  async execute(input, context) {
    const { callbacks } = context;
    const pluginId = (input.plugin_id ?? "").trim();
    const enable = input.enable !== false;
    if (!pluginId) {
      callbacks.pushToolResult(this.formatError(new Error("plugin_id parameter is required")));
      return;
    }
    try {
      const plugins = this.app.plugins;
      if (!plugins) {
        callbacks.pushToolResult(this.formatError(new Error("Plugin system not available")));
        return;
      }
      const manifests = plugins.manifests ?? {};
      if (!manifests[pluginId]) {
        const similar = Object.keys(manifests).filter((id) => id.includes(pluginId) || pluginId.includes(id)).slice(0, 5);
        const hint = similar.length > 0 ? ` Similar plugin IDs: ${similar.join(", ")}` : "";
        callbacks.pushToolResult(
          this.formatError(new Error(`Plugin "${pluginId}" is not installed.${hint}`))
        );
        return;
      }
      const isCurrentlyEnabled = plugins.enabledPlugins?.has(pluginId) ?? false;
      const pluginName = manifests[pluginId]?.name ?? pluginId;
      if (enable && isCurrentlyEnabled) {
        callbacks.pushToolResult(
          this.formatSuccess(`Plugin "${pluginName}" is already enabled.`)
        );
        return;
      }
      if (!enable && !isCurrentlyEnabled) {
        callbacks.pushToolResult(
          this.formatSuccess(`Plugin "${pluginName}" is already disabled.`)
        );
        return;
      }
      if (enable) {
        await plugins.enablePlugin(pluginId);
        await new Promise((r) => setTimeout(r, 500));
        const scanner = this.plugin.vaultDNAScanner;
        if (scanner) {
          try {
            await scanner.handlePluginEnabled(pluginId);
          } catch (e) {
            console.warn("[EnablePlugin] VaultDNA update failed:", e);
          }
        }
        callbacks.pushToolResult(
          this.formatSuccess(
            `Plugin "${pluginName}" has been enabled successfully. NEXT STEP: Read the skill file with read_file(".obsidian-agent/plugin-skills/${pluginId}.skill.md") to learn the available commands, then use execute_command to run them.`
          )
        );
      } else {
        await plugins.disablePlugin(pluginId);
        const scanner = this.plugin.vaultDNAScanner;
        if (scanner) {
          try {
            await scanner.handlePluginDisabled(pluginId);
          } catch (e) {
            console.warn("[EnablePlugin] VaultDNA update failed:", e);
          }
        }
        callbacks.pushToolResult(
          this.formatSuccess(`Plugin "${pluginName}" has been disabled.`)
        );
      }
      callbacks.log(`Plugin ${enable ? "enabled" : "disabled"}: ${pluginName} (${pluginId})`);
    } catch (error2) {
      callbacks.pushToolResult(this.formatError(error2));
      await callbacks.handleError("enable_plugin", error2);
    }
  }
};

